from pathlib import Path
import json,html
root=Path(__file__).parent
out=root/'dist'
source='https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-Consumer/'
guides=[
('whey-protein','Whey protein','Protein','Compare concentrate, isolate, and the label behind the scoop.','Compare protein grams per serving, ingredient lists, milk allergens, and total cost. Concentrate and isolate are different product formats; choose based on your dietary needs and the actual label, rather than premium branding.','Protein grams per serving|Milk allergen statement|Sweeteners and flavorings|Cost per serving','Compare the cost for the amount of protein you intend to buy. A smaller scoop can make a tub appear to contain more servings without providing better value.'),
('plant-protein','Plant protein','Protein','Find a plant-based powder that fits your preferences.','Start with the protein source: pea, soy, rice, or a blend. Check every ingredient if you avoid animal products; a plant-themed label does not substitute for reading the full formula.','Protein source|Allergen statement|Protein per serving|Texture and flavor','Buy a small size first if taste matters to your routine. A large discounted tub is poor value if you will not use it.'),
('creatine','Creatine monohydrate','Strength','A straightforward checklist for comparing creatine labels.','Compare clearly labeled creatine monohydrate products. A single-ingredient formula is easier to evaluate than a blend. This guide compares packaging and value; it does not prescribe a dose or guarantee results.','Named ingredient form|Amount per serving|Number of servings|Independent certification','Calculate cost per gram of the listed creatine ingredient. Do not compare scoop sizes when one scoop also contains flavorings or other ingredients.'),
('pre-workout','Pre-workout','Training','Read the whole formula before choosing a blend.','Compare disclosed ingredient quantities and caffeine information. A proprietary blend can make products difficult to compare because individual amounts may be unclear. More ingredients do not establish better performance.','Caffeine disclosure|Individual ingredient quantities|Serving size|Other stimulant ingredients','Compare the full serving, not the front-label claims. Check whether the directions define one serving as more than one scoop.'),
('stimulant-free','Stimulant-free pre-workout','Training','Compare formulas without relying on energy claims.','Read all ingredients rather than assuming that a stimulant-free marketing label answers every question. Ask the manufacturer about unclear ingredients. Evidence for a finished multi-ingredient product can differ from research on one component.','Full ingredient list|Disclosed amounts|Certification|Cost per serving','Pay for ingredients you can identify and evaluate. A long label is not evidence of greater value.'),
('electrolytes','Electrolyte mixes','Hydration','Compare what is actually in each packet.','Electrolyte mixes vary in sodium, other minerals, carbohydrates, and sweeteners. Compare the prepared serving using the recommended water volume; packet weight alone is not a useful comparison.','Sodium per serving|Sugar and carbohydrates|Mixing volume|Dietary restrictions','Compare cost per prepared serving and the package directions. Different formulas serve different preferences; this is not a universal recommendation to supplement.'),
('protein-bars','Protein bars','Protein','Read beyond the protein number on the wrapper.','Compare the entire nutrition label, ingredients, and allergens. Bar size varies, so compare both per bar and per equal weight when assessing value. A convenient snack is not automatically a complete meal.','Protein per bar|Calories and serving size|Allergens|Sweeteners and texture','Start with a single bar before buying a box. Flavor, texture, and your own tolerance determine whether the purchase is practical.'),
('budget-protein','Protein powder on a budget','Value','Use a consistent comparison instead of tub size.','Record the package price, number of servings, and protein per serving. Compare equivalent protein quantities across the products you are considering. Keep shipping and recurring subscription terms in the total.','Total delivered price|Protein quantity|Subscription conditions|Return policy','Divide the total price by total protein grams, then multiply by 25 to compare cost for 25 grams of protein. This is a shopping unit, not a suggested dose.'),
('third-party-testing','Third-party testing','Quality','Check certification claims at their source.','Look for the exact certification program, product, and variant. A brand-wide statement or a laboratory-looking graphic does not establish that every item is certified. Confirm claims in the certifier’s directory.','Exact product name|Certifier directory listing|Scope of testing|Lot details when available','Certification can help you evaluate a claim, but does not promise that a supplement works or is appropriate for you.'),
('beginner-checklist','Before buying your first supplement','Essentials','Start with a need, a label, and a realistic budget.','Identify why you are considering a supplement and what information would justify the purchase. Review food, training, and practical constraints first. Avoid buying a large stack simply because several products are marketed together.','Reason for purchase|Full label|Total monthly cost|Questions for a qualified clinician','Buy only what you can justify. Skip guarantees of rapid transformation and seek professional guidance for personal health decisions.')]
css='''*{box-sizing:border-box}body{margin:0;background:#f6f5f0;color:#18261f;font:17px/1.65 system-ui,sans-serif}a{color:inherit}header,main,footer{max-width:1180px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{font-size:21px;font-weight:900;text-decoration:none;letter-spacing:-1px}nav{display:flex;gap:22px;font-size:14px}nav a{text-decoration:none}.hero{background:#182f25;color:#fff;border-radius:24px;padding:65px 8%;margin:20px 0 42px;position:relative;overflow:hidden}.hero:after{content:'+';position:absolute;right:3%;top:-90px;font-size:400px;line-height:1;color:#b4ec7020;pointer-events:none}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:2px;font-weight:800;color:#52713d}.hero .eyebrow{color:#c2f48f}h1{font-size:clamp(38px,6vw,72px);line-height:1.04;letter-spacing:-3px;max-width:760px;margin:20px 0}h2{font-size:30px;letter-spacing:-1px}.lead{max-width:620px;font-size:20px}.button{display:inline-block;background:#c2f48f;color:#182f25;padding:12px 20px;border-radius:6px;text-decoration:none;font-weight:750}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:white;border:1px solid #dedfd7;padding:26px;border-radius:12px;display:flex;flex-direction:column}.card h3{line-height:1.2;font-size:24px}.card p{flex:1;color:#56615a}.card a{font-weight:750;text-underline-offset:5px}.note{background:#e9eddf;border-radius:10px;padding:18px;font-size:14px;margin:24px 0}.tools{display:flex;gap:15px;flex-wrap:wrap;margin:24px 0}input,select{font:inherit;padding:12px;border:1px solid #8b9789;border-radius:6px;background:#fff}input{flex:1;min-width:200px}article{max-width:780px;margin:36px auto 70px}article h1{font-size:48px}li{margin:9px 0}footer{border-top:1px solid #d8dcd1;font-size:14px}footer a{margin-right:18px}.calc{background:white;border:1px solid #dedfd7;border-radius:12px;padding:26px;margin:42px 0}.calc label{display:block;margin:12px 0}.calc input{width:100%}output{font-size:24px;font-weight:800}.empty{display:none}a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #7f44cb;outline-offset:4px}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}header{align-items:flex-start;flex-direction:column}.hero{padding:38px 26px}.hero:after{display:none}}@media(max-width:520px){.grid{grid-template-columns:1fr}nav{gap:15px}main{padding:16px}h1,article h1{font-size:40px;letter-spacing:-1.5px}}'''
(out/'styles.css').write_text(css)
def page(title,body,path,desc):
 canonical='https://fitgear-authority.netlify.app/'+path
 text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | FitGear Authority</title><meta name="description" content="{html.escape(desc,quote=True)}"><link rel="canonical" href="{canonical}"><link rel="stylesheet" href="/styles.css"></head><body><header><a class="brand" href="/">FITGEAR<span style="color:#608e37"> AUTHORITY</span></a><nav aria-label="Main"><a href="/#guides">Buying guides</a><a href="/#calculator">Value calculator</a><a href="/about.html">Our approach</a></nav></header><main>{body}</main><footer><p>FitGear Authority · Supplement shopping, explained.</p><a href="/about.html">About & editorial policy</a><a href="/disclosure.html">Affiliate disclosure</a><a href="/privacy.html">Privacy</a><p>Educational shopping information for adults. Not medical advice. No claims of hands-on product testing.</p></footer></body></html>'''
 (out/path).write_text(text)
cards=''
for i,(slug,title,cat,desc,intro,checks,value) in enumerate(guides,1):
 cards+=f'<div class="card" data-category="{cat}" data-title="{title.lower()}"><span class="eyebrow">{i:02} / {cat}</span><h3>{title}</h3><p>{desc}</p><a href="/guides/{slug}.html">Read buying guide →</a></div>'
 body=f'<article><a href="/#guides">← All buying guides</a><p class="eyebrow">{cat} / Buying guide</p><h1>{title}</h1><p class="lead">{desc}</p><p>Published November 1, 2026 · FitGear Authority editorial</p><div class="note">Independent shopping guide. No paid rankings, hands-on testing claims, or active affiliate links.</div><h2>Where to start</h2><p>{intro}</p><h2>What to compare</h2><ul>'+''.join(f'<li>{c}</li>' for c in checks.split('|'))+f'</ul><h2>How to judge value</h2><p>{value}</p><h2>Before you buy</h2><p>Read the current label, confirm the seller and expiration details, and check shipping and returns. Product formulas and terms can change. Discuss suitability, medications, and health concerns with a qualified healthcare professional.</p><h2>Sources and further reading</h2><p><a href="{source}">NIH Office of Dietary Supplements: exercise and athletic performance</a>. This source provides background on supplement evidence and safety; our shopping checklists are editorial guidance.</p><p><a href="https://www.nsf.org/consumer-resources/articles/supplement-vitamins-certification">NSF: supplement certification</a></p><p><a href="/disclosure.html">How affiliate links will be disclosed</a></p></article>'
 page(title,body,f'guides/{slug}.html',desc)
body=f'''<section class="hero"><p class="eyebrow">Know the label. Keep the value.</p><h1>Less supplement hype.<br>Smarter choices.</h1><p class="lead">Straightforward buying guides for everyday lifters. Compare ingredients, labels, and cost before spending your money.</p><a class="button" href="#guides">Find your buying guide ↗</a></section><div class="note">Our approach: clear shopping criteria, linked sources, and honest limits. We have not tested or ranked specific products. There are currently no commission-earning links.</div><section id="guides"><p class="eyebrow">The guide library</p><h2>Start with what you’re shopping for.</h2><div class="tools"><input id="search" type="search" placeholder="Search guides…" aria-label="Search buying guides"><select id="category" aria-label="Filter category"><option value="">All categories</option>'''+''.join(f'<option>{c}</option>' for c in sorted(set(x[2] for x in guides)))+f'''</select></div><p id="count" aria-live="polite">10 guides</p><div class="grid">{cards}</div><p id="empty" hidden>No matching guides. Try a different search.</p></section><section class="calc" id="calculator"><p class="eyebrow">Check the math</p><h2>Protein value calculator</h2><p>Compare cost per 25 grams of protein. This is a comparison unit, not a recommended serving.</p><label>Total price ($)<input id="price" type="number" min="0.01" step="0.01" value="40"></label><label>Servings in the package<input id="servings" type="number" min="0.01" step="any" value="30"></label><label>Protein grams per serving<input id="grams" type="number" min="0.01" step="any" value="25"></label><output id="result" aria-live="polite"></output></section><script src="/app.js" defer></script>'''
page('Supplement buying guides',body,'index.html','Supplement buying guides with clear label comparisons and a protein value calculator.')
page('Our approach','<article><h1>Clear criteria. Honest limits.</h1><p>FitGear Authority publishes supplement shopping guides for adults who want to understand labels and compare value.</p><h2>Editorial policy</h2><p>These are category buying guides, not hands-on product reviews. We do not invent test results, customer testimonials, product rankings, or medical credentials. Sources are linked where relevant. Prices and formulas must be checked with the seller.</p><h2>Corrections</h2><p>Report a factual issue through <a href="https://github.com/jrklouis-collab/fitgear-authority/issues">our public issue tracker</a>. Do not include private or medical information.</p></article>','about.html','How FitGear Authority creates its supplement shopping guides.')
page('Affiliate disclosure','<article><h1>Affiliate disclosure</h1><p>There are currently no active affiliate links on this website, and purchases cannot generate commissions for this site.</p><p>If approved affiliate links are added, they will be identified near the relevant links. FitGear Authority may then earn a commission from qualifying purchases at no extra cost to the shopper. Compensation will not be presented as product testing or proof of effectiveness.</p></article>','disclosure.html','Our current affiliate link status and disclosure policy.')
page('Privacy','<article><h1>Privacy</h1><p>This website does not run analytics, advertising scripts, tracking pixels, email signups, or account registration. Search and calculator inputs are processed in your browser and are not sent to us by this website.</p><p>The hosting provider may process technical request data needed to deliver and secure the site. External sites have their own privacy practices. Please avoid putting private information into public GitHub issues.</p><p>Updated November 1, 2026.</p></article>','privacy.html','How this website handles visitor information.')
page('Page not found','<article><h1>Let’s get you back on track.</h1><p>This page could not be found.</p><a class="button" href="/">Browse the buying guides</a></article>','404.html','Page not found.')
(out/'app.js').write_text('''const search=document.querySelector('#search'), category=document.querySelector('#category');function filter(){let n=0;document.querySelectorAll('.card').forEach(c=>{const show=c.textContent.toLowerCase().includes(search.value.trim().toLowerCase())&&(!category.value||c.dataset.category===category.value);c.hidden=!show;c.style.display=show?'flex':'none';if(show)n++});document.querySelector('#count').textContent=n+' guide'+(n===1?'':'s');document.querySelector('#empty').hidden=n!==0}search.addEventListener('input',filter);category.addEventListener('change',filter);function calc(){const values=['price','servings','grams'].map(id=>Number(document.getElementById(id).value));document.querySelector('#result').textContent=values.every(v=>Number.isFinite(v)&&v>0)?'$'+(values[0]/(values[1]*values[2])*25).toFixed(2)+' per 25 g protein':'Enter a positive number in every field.'}['price','servings','grams'].forEach(id=>document.getElementById(id).addEventListener('input',calc));calc();''')
(out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://fitgear-authority.netlify.app/sitemap.xml\n')
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://fitgear-authority.netlify.app/'+str(p.relative_to(out))+'</loc></url>' for p in sorted(out.rglob('*.html')) if p.name!='404.html')+'</urlset>')
(root/'netlify.toml').write_text('[build]\n  publish = "dist"\n\n[[headers]]\n  for = "/*"\n  [headers.values]\n    X-Content-Type-Options = "nosniff"\n    Referrer-Policy = "strict-origin-when-cross-origin"\n')
print('Built',len(list(out.rglob('*.html'))),'pages, including',len(guides),'guides')
